SELECT monthly_fee_bucket, pct_premium FROM (SELECT CASE WHEN monthly_fee >= 232 THEN 'high' WHEN monthly_fee >= 57 THEN 'mid' ELSE 'low' END monthly_fee_bucket, ROUND((100 * SUM(CASE WHEN plan = 'premium' THEN 1 ELSE 0 END)) / COUNT(*), 1) pct_premium FROM subscriptions GROUP BY CASE WHEN monthly_fee >= 232 THEN 'high' WHEN monthly_fee >= 57 THEN 'mid' ELSE 'low' END) agg WHERE pct_premium > 27;
